const rows = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
const retrievedAt = new Date().toISOString();
const normalized = rows.map((coin) => {
  const asset = String(coin.id ?? '').trim().toLowerCase();
  const price = Number(coin.current_price);
  const marketCap = Number(coin.market_cap);
  const change = coin.price_change_percentage_24h == null ? null : Number(coin.price_change_percentage_24h);
  if (!asset || !Number.isFinite(price) || price < 0) return null;
  return {
    asset,
    symbol: String(coin.symbol ?? '').toUpperCase(),
    name: String(coin.name ?? asset),
    price_usd: price,
    market_cap_usd: Number.isFinite(marketCap) ? marketCap : null,
    change_24h_percent: Number.isFinite(change) ? change : null,
    retrieved_at: retrievedAt
  };
}).filter(Boolean);
if (normalized.length === 0) throw new Error('No valid market records returned by the API. Check the HTTP response and API availability.');
return normalized.map(record => ({ json: record }));

const records = $input.all().map(item => item.json);
const lines = records.map(r => `${r.name} (${r.symbol}): $${r.price_usd.toLocaleString('en-US', { maximumFractionDigits: 6 })} | 24h: ${r.change_24h_percent == null ? 'N/A' : `${r.change_24h_percent.toFixed(2)}%`}`);
return [{ json: { title: 'Crypto Market Snapshot', retrieved_at: new Date().toISOString(), asset_count: records.length, assets: records, summary: lines.join('\n') } }];
